          key: 'minimum_quantity',
          value: quantity,
          valueType: 'number_integer',
        });

        if (resultBanner) {
          root.removeChild(resultBanner);
        }

        if (result.type === 'success') {
          resultBanner = root.createComponent(
            Banner,
            {status: 'success'},
            'Minimum quantity configured',
