      ) : (
        &lt;Image
          source="https://cdn.shopify.com/s/files/placeholder-images/product.png"
          accessibilityLabel="Product preview"
          loading="lazy"
          onLoad={() =&gt; setLoading(false)}
          onError={() =&gt; {
            setLoading(false);
            setError(true);
          }}
        /&gt;
      )}
    &lt;/BlockStack&gt;
  );
}

